#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
================================================================================
FILE ĐỘC LẬP TỰ GIẢI NÉN & ĐỒNG BỘ 1 MẠCH 5 MẪU GỐC COMMERCIAL PRO VÀO VS CODE & GITHUB
Repository mục tiêu: https://github.com/gia417808-dot/Web-App-Template
================================================================================
Chỉ cần đặt file này vào thư mục dự án trong VS Code và chạy:
    python unpack_and_sync_all_5.py --push
Toàn bộ 20 file mã nguồn chuẩn của 5 mẫu (GS-001 v4.0, GS-002 v3.0, GS-003 v4.1,
GS-004 v4.4, GS-005 v3.3) sẽ tự động được bung ra đúng thư mục và đẩy lên GitHub!
"""

import os
import json
import zlib
import base64
import argparse
import subprocess
from datetime import datetime

REPO_URL = "https://github.com/gia417808-dot/Web-App-Template.git"

EMBEDDED_ARCHIVE_B64 = ""


def unpack_and_sync(target_dir=".", do_push=False, branch=""):
    raw_bytes = zlib.decompress(base64.b64decode(EMBEDDED_ARCHIVE_B64.encode("ascii")))
    files_dict = json.loads(raw_bytes.decode("utf-8"))

    os.makedirs(target_dir, exist_ok=True)
    print("=" * 74)
    print(f"🚀 ĐANG BUNG & ĐỒNG BỘ {len(files_dict)} FILE CỦA 5 MẪU GỐC VÀO: {os.path.abspath(target_dir)}")
    print("=" * 74)

    for rel_path, content in files_dict.items():
        full_path = os.path.join(target_dir, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, "w", encoding="utf-8") as f:
            f.write(content)
        print(f"  ✅ Đã ghi: {rel_path} ({len(content):,} ký tự)")

    if do_push:
        print("\n🔄 Đang thực hiện đồng bộ Git & đẩy lên GitHub...")
        if not os.path.exists(os.path.join(target_dir, ".git")):
            subprocess.run(["git", "init"], cwd=target_dir, check=False)
            subprocess.run(["git", "remote", "add", "origin", REPO_URL], cwd=target_dir, check=False)
        subprocess.run(["git", "add", "-A"], cwd=target_dir, check=False)
        stamp = datetime.now().strftime("%Y-%m-%d %H:%M")
        msg = f"feat(commercial-pro): sync all 5 Golden Master templates (GS-001..GS-005) [{stamp}]"
        subprocess.run(["git", "commit", "-m", msg], cwd=target_dir, check=False)
        if not branch:
            res = subprocess.run(["git", "rev-parse", "--abbrev-ref", "HEAD"], cwd=target_dir, text=True, capture_output=True)
            branch = (res.stdout or "").strip() or "main"
            if branch == "HEAD":
                branch = "main"
                subprocess.run(["git", "branch", "-M", "main"], cwd=target_dir, check=False)
        subprocess.run(["git", "push", "-u", "origin", branch], cwd=target_dir, check=False)
        print("\n🎉 HOÀN TẤT ĐỒNG BỘ & PUSH 5 MẪU GỐC LÊN GITHUB!")
    else:
        print("\n💡 Đã ghi toàn bộ 5 mẫu gốc vào thư mục! Để tự động commit & push lên GitHub, chạy:")
        print("   python unpack_and_sync_all_5.py --push")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-dir", default=".", help="Thư mục gốc của repo Web-App-Template trong VS Code")
    parser.add_argument("--push", action="store_true", help="Tự động git add, commit và push lên GitHub")
    parser.add_argument("--branch", default="", help="Nhánh Git (mặc định tự nhận diện main/master)")
    args = parser.parse_args()
    unpack_and_sync(args.repo_dir, do_push=args.push, branch=args.branch)
